// Secure secrets management module
// Supports multiple backends: environment variables, AWS Secrets Manager, local files

const { SecretsManager } = require('@aws-sdk/client-secrets-manager');

class SecretManager {
  constructor() {
    this.secrets = new Map();
    this.initialized = false;
  }

  // Initialize secrets - chooses appropriate backend based on environment
  async initialize() {
    if (this.initialized) return;

    try {
      if (process.env.NODE_ENV === 'production' && process.env.AWS_REGION) {
        // Use AWS Secrets Manager in production
        await this.loadFromAWSSecretsManager();
      } else if (process.env.NODE_ENV === 'test') {
        // Use mock secrets for testing
        await this.loadMockSecrets();
      } else {
        // Fall back to environment variables for development
        await this.loadFromEnvironment();
      }

      this.initialized = true;
      console.log('Secrets initialized successfully');
    } catch (error) {
      console.error('Failed to initialize secrets:', error.message);
      throw error;
    }
  }

  // Load from AWS Secrets Manager
  async loadFromAWSSecretsManager() {
    const client = new SecretsManager({
      region: process.env.AWS_REGION
    });

    const secretNames = [
      'database-credentials',
      'api-keys',
      'jwt-secret'
    ];

    for (const secretName of secretNames) {
      try {
        const data = await client.getSecretValue({ SecretId: secretName });
        if (data.SecretString) {
          const secrets = JSON.parse(data.SecretString);
          Object.entries(secrets).forEach(([key, value]) => {
            this.secrets.set(key, value);
          });
        }
      } catch (error) {
        console.warn(`Failed to load secret ${secretName}:`, error.message);
      }
    }
  }

  // Load from environment variables
  async loadFromEnvironment() {
    const envVars = [
      'DATABASE_URL',
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY',
      'JWT_SECRET',
      'STRIPE_SECRET_KEY',
      'ANTHROPIC_API_KEY',
      'LOGFIRE_TOKEN'
    ];

    envVars.forEach(key => {
      if (process.env[key]) {
        this.secrets.set(key, process.env[key]);
      }
    });
  }

  // Mock secrets for testing
  async loadMockSecrets() {
    this.secrets.set('DATABASE_URL', 'postgres://test:test@localhost:5432/test');
    this.secrets.set('JWT_SECRET', 'test-jwt-secret-for-development');
    this.secrets.set('STRIPE_SECRET_KEY', 'sk-test-mockkey123');
  }

  // Get a secret
  get(key) {
    if (!this.initialized) {
      throw new Error('Secrets not initialized. Call initialize() first.');
    }

    const value = this.secrets.get(key);
    if (!value) {
      throw new Error(`Secret ${key} not found`);
    }

    return value;
  }

  // Check if secret exists
  has(key) {
    return this.secrets.has(key);
  }
}

// Singleton instance
module.exports = new SecretManager();

