const secretManager = require('../config/secrets');

// Mock environment for testing
process.env.NODE_ENV = 'test';

describe('Secret Manager', () => {
  beforeAll(async () => {
    await secretManager.initialize();
  });

  test('should initialize with mock secrets in test environment', () => {
    expect(secretManager.has('DATABASE_URL')).toBe(true);
    expect(secretManager.has('JWT_SECRET')).toBe(true);
  });

  test('should return mock database URL', () => {
    const dbUrl = secretManager.get('DATABASE_URL');
    expect(dbUrl).toBe('postgres://test:test@localhost:5432/test');
  });

  test('should throw error for non-existent secret', () => {
    expect(() => {
      secretManager.get('NON_EXISTENT_SECRET');
    }).toThrow('Secret NON_EXISTENT_SECRET not found');
  });

  test('should handle uninitialized access', () => {
    // Create a new instance to test uninitialized state
    const SecretManager = require('../config/secrets').constructor;
    const manager = new SecretManager();

    expect(() => {
      manager.get('ANY_SECRET');
    }).toThrow('Secrets not initialized');
  });
});

