// Advanced secrets management with fallback strategies

class SecretManager {
  constructor() {
    this.secrets = new Map();
    this.loaded = false;
  }

  // Load secrets based on environment
  async loadSecrets() {
    if (this.loaded) return;

    try {
      // Priority 1: Cloud secrets manager (AWS Secrets Manager, Azure Key Vault, etc.)
      if (process.env.NODE_ENV === 'production') {
        await this.loadFromCloudSecretsManager();
      }

      // Priority 2: Environment variables (with validation)
      this.loadFromEnvironment();

      // Priority 3: Local .env file (development only)
      if (process.env.NODE_ENV !== 'production') {
        this.loadFromDotEnv();
      }

      this.validateSecrets();
      this.loaded = true;

    } catch (error) {
      console.error('Failed to load secrets:', error.message);
      throw error;
    }
  }

  // Mock cloud secrets manager integration
  async loadFromCloudSecretsManager() {
    // In real implementation, this would connect to AWS Secrets Manager,
    // Azure Key Vault, HashiCorp Vault, etc.
    console.log('Loading secrets from cloud secrets manager...');

    // Simulate async secret loading
    return new Promise((resolve) => {
      setTimeout(() => {
        // These would come from actual cloud API calls
        const cloudSecrets = {
          DATABASE_URL: process.env.DATABASE_URL || 'cloud-database-url',
          JWT_SECRET: process.env.JWT_SECRET || 'cloud-jwt-secret-minimum-32-chars-long',
          AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
          AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY
        };

        Object.entries(cloudSecrets).forEach(([key, value]) => {
          if (value) this.secrets.set(key, value);
        });

        resolve();
      }, 100);
    });
  }

  loadFromEnvironment() {
    const envVars = [
      'NODE_ENV', 'PORT', 'JWT_SECRET', 'DATABASE_URL', 
      'ALLOWED_ORIGINS', 'AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY',
      'STRIPE_SECRET_KEY', 'ANTHROPIC_API_KEY', 'LOGFIRE_TOKEN'
    ];

    envVars.forEach(key => {
      if (process.env[key]) {
        this.secrets.set(key, process.env[key]);
      }
    });
  }

  loadFromDotEnv() {
    // Already loaded by dotenv.config(), just ensure they're in our map
    this.loadFromEnvironment();
  }

  validateSecrets() {
    const required = [];

    if (this.get('NODE_ENV') === 'production') {
      required.push('JWT_SECRET', 'DATABASE_URL');

      // Validate JWT secret length
      const jwtSecret = this.get('JWT_SECRET');
      if (jwtSecret && jwtSecret.length < 32) {
        throw new Error('JWT_SECRET must be at least 32 characters long');
      }
    }

    const missing = required.filter(key => !this.secrets.has(key));
    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }
  }

  get(key, defaultValue = null) {
    if (!this.loaded) {
      throw new Error('Secrets not loaded. Call loadSecrets() first.');
    }
    return this.secrets.get(key) || defaultValue;
  }

  // Mask sensitive values for logging
  maskSensitiveValue(value, visibleChars = 4) {
    if (!value || typeof value !== 'string') return '***';
    if (value.length <= visibleChars * 2) return '***';

    const firstPart = value.substring(0, visibleChars);
    const lastPart = value.substring(value.length - visibleChars);
    return `${firstPart}***${lastPart}`;
  }
}

