      Object.entries(secrets).forEach(([key, value]) => {
        if (!value) {
          throw new Error(`Missing required secret: ${key}`);
        }
      });
    }

    // Cache the secrets
    Object.entries(secrets).forEach(([key, value]) => {
      this.cache.set(key, value);
