// Secure secrets management with fallback strategies

const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.secretsCache = new Map();
    this.cacheTimeout = 5 * 60 * 1000; // 5 minutes
  }

  // AWS Secrets Manager integration
  async getAWSecret(secretName) {
    try {
      const client = new SecretsManagerClient({
        region: process.env.AWS_REGION || 'us-east-1'
      });

      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await client.send(command);

      if (response.SecretString) {
        return JSON.parse(response.SecretString);
      }

      throw new Error('Secret not found in AWS Secrets Manager');
    } catch (error) {
      console.warn(`AWS Secrets Manager error for ${secretName}:`, error.message);
      return null;
    }
  }

  // Environment variable fallback with validation
  getEnvSecret(secretName, defaultValue = null) {
    const value = process.env[secretName];
    if (!value && defaultValue === null) {
      throw new Error(`Required secret ${secretName} not found in environment`);
    }
    return value || defaultValue;
  }

  // Get secret with prioritized sources
  async getSecret(secretName, options = {}) {
    const {
      awsSecretName = secretName,
      defaultValue = null,
      cache = true
    } = options;

    // Check cache first
    if (cache && this.secretsCache.has(secretName)) {
      const cached = this.secretsCache.get(secretName);
      if (Date.now() - cached.timestamp < this.cacheTimeout) {
        return cached.value;
      }
    }

    // Try AWS Secrets Manager first (for production)
    if (process.env.NODE_ENV === 'production' && process.env.USE_AWS_SECRETS === 'true') {
      const awsSecret = await this.getAWSecret(awsSecretName);
      if (awsSecret) {
        if (cache) {
          this.secretsCache.set(secretName, {
            value: awsSecret,
            timestamp: Date.now()
          });
        }
        return awsSecret;
      }
    }

    // Fallback to environment variables
    const envSecret = this.getEnvSecret(secretName, defaultValue);

    if (cache) {
      this.secretsCache.set(secretName, {
        value: envSecret,
        timestamp: Date.now()
      });
    }

    return envSecret;
  }

  // Clear cache (useful for secret rotation)
  clearCache(secretName = null) {
    if (secretName) {
      this.secretsCache.delete(secretName);
    } else {
      this.secretsCache.clear();
    }
  }
}

// Singleton instance
module.exports = new SecretsManager();

// Secure environment configuration with validation

const Joi = require('joi');
const secretsManager = require('./secrets-manager');

// Environment schema validation
const envSchema = Joi.object({
  // Node environment
  NODE_ENV: Joi.string().valid('development', 'production', 'test').default('development'),

  // Server configuration
  PORT: Joi.number().default(3000),
  HOST: Joi.string().hostname().default('localhost'),

  // Security secrets (required in production)
  JWT_SECRET: Joi.string().min(32).when('NODE_ENV', {
    is: 'production',
    then: Joi.required(),
    otherwise: Joi.optional()
  }),

  // CORS configuration
  ALLOWED_ORIGINS: Joi.string().default('http://localhost:3000'),

  // Database (if used)
  DATABASE_URL: Joi.string().uri().optional(),

  // External services
  AWS_ACCESS_KEY_ID: Joi.string().optional(),
  AWS_SECRET_ACCESS_KEY: Joi.string().optional(),
  AWS_REGION: Joi.string().default('us-east-1'),

  // Secrets manager configuration
  USE_AWS_SECRETS: Joi.boolean().default(false),

  // Rate limiting
  RATE_LIMIT_WINDOW_MS: Joi.number().default(900000),
  RATE_LIMIT_MAX_REQUESTS: Joi.number().default(100)
}).unknown(true); // Allow other environment variables

class Config {
  constructor() {
    this.config = {};
    this.initialized = false;
  }

  async initialize() {
    if (this.initialized) return;

    // Load environment variables
    require('dotenv').config();

    // Validate environment variables
    const { error, value: envVars } = envSchema.validate(process.env);
    if (error) {
      throw new Error(`Environment validation error: ${error.message}`);
    }

    // Load secrets from secure sources
    await this.loadSecrets(envVars);

    this.initialized = true;
  }

  async loadSecrets(envVars) {
    // Load JWT secret securely
    this.config.JWT_SECRET = await secretsManager.getSecret('JWT_SECRET', {
      defaultValue: envVars.JWT_SECRET,
      cache: true
    });

    // Validate that required secrets are present in production
    if (envVars.NODE_ENV === 'production') {
      if (!this.config.JWT_SECRET) {
        throw new Error('JWT_SECRET is required in production environment');
      }
    }

    // Copy other configuration
    this.config = { ...envVars, ...this.config };
  }

  get(key, defaultValue = null) {
    if (!this.initialized) {
      throw new Error('Config not initialized. Call await config.initialize() first');
    }

    const value = this.config[key];
    if (value === undefined && defaultValue === null) {
      throw new Error(`Configuration key ${key} not found`);
    }

    return value !== undefined ? value : defaultValue;
  }

  getAll() {
    if (!this.initialized) {
      throw new Error('Config not initialized');
    }

    return { ...this.config };
  }

  // Method to refresh secrets (useful for rotation)
  async refreshSecrets() {
    secretsManager.clearCache();
    await this.loadSecrets(this.config);
  }
}

// Singleton instance
module.exports = new Config();

// Production-ready secure Express application with proper secrets management

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const { body, query, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');

const config = require('./config');

const app = express();

// Initialize configuration
async function initializeApp() {
  try {
    await config.initialize();

    // Security middleware
    app.use(helmet());

    // CORS configuration
    app.use(cors({
      origin: config.get('ALLOWED_ORIGINS').split(','),
      credentials: true
    }));

    // Rate limiting
    const limiter = rateLimit({
      windowMs: config.get('RATE_LIMIT_WINDOW_MS'),
      max: config.get('RATE_LIMIT_MAX_REQUESTS'),
      message: 'Too many requests from this IP, please try again later.'
    });
    app.use(limiter);

    // Request logging
    app.use(morgan('combined'));

    // Body parsing middleware
    app.use(express.json({ limit: '10kb' }));
    app.use(express.urlencoded({ extended: true, limit: '10kb' }));

    // Authentication middleware
    const authenticateToken = (req, res, next) => {
      const authHeader = req.headers['authorization'];
      const token = authHeader && authHeader.split(' ')[1];

      if (!token) {
        return res.status(401).json({ error: 'Access token required' });
      }

      jwt.verify(token, config.get('JWT_SECRET'), (err, user) => {
        if (err) return res.status(403).json({ error: 'Invalid token' });
        req.user = user;
        next();
      });
    };

    // Routes
    app.get('/health', (req, res) => {
      res.json({ 
        status: 'ok', 
        timestamp: new Date().toISOString(),
        environment: config.get('NODE_ENV')
      });
    });

    app.get('/users', [
      authenticateToken,
      query('page').isInt({ min: 1 }).optional().withMessage('Page must be a positive integer'),
      query('limit').isInt({ min: 1, max: 100 }).optional().withMessage('Limit must be between 1 and 100')
    ], (req, res) => {
      // Input validation
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ errors: errors.array() });
      }

      // Return sanitized user data
      res.json([
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ]);
    });

    // Error handling middleware
    app.use((err, req, res, next) => {
      console.error('Error:', err.stack);
      res.status(500).json({ 
        error: 'Something went wrong!',
        message: config.get('NODE_ENV') === 'development' ? err.message : 'Internal server error'
      });
    });

    // 404 handler
    app.use((req, res) => {
      res.status(404).json({ error: 'Route not found' });
    });

    const PORT = config.get('PORT');
    const HOST = config.get('HOST');

    app.listen(PORT, HOST, () => {
      console.log(`Secure server running on ${HOST}:${PORT}`);
      console.log(`Environment: ${config.get('NODE_ENV')}`);
      console.log(`Secrets managed via: ${config.get('USE_AWS_SECRETS') ? 'AWS Secrets Manager' : 'Environment variables'}`);
    });

  } catch (error) {
    console.error('Failed to initialize application:', error.message);
    process.exit(1);
  }
}

// Handle graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  process.exit(0);
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  process.exit(0);
});

// Start the application
initializeApp();

module.exports = app;

