// Secure secrets management
// Use AWS Secrets Manager, HashiCorp Vault, or similar in production

const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.secrets = {};
    this.initialized = false;
  }

  async init() {
    if (this.initialized) return;

    // For development, use safe fallbacks or error
    if (process.env.NODE_ENV === 'production') {
      await this.loadFromAWSSecretsManager();
    } else {
      // Development - use environment variables with validation
      this.validateDevelopmentSecrets();
    }

    this.initialized = true;
  }

  async loadFromAWSSecretsManager() {
    try {
      const client = new SecretsManagerClient({
        region: process.env.AWS_REGION || 'us-east-1'
      });

      // Load multiple secrets as needed
      const command = new GetSecretValueCommand({
        SecretId: process.env.AWS_SECRETS_NAME
      });

      const response = await client.send(command);
      this.secrets = JSON.parse(response.SecretString);
    } catch (error) {
      console.error('Failed to load secrets from AWS:', error);
      throw new Error('Secrets initialization failed');
    }
  }

  validateDevelopmentSecrets() {
    const requiredSecrets = [
      'JWT_SECRET',
      'SESSION_SECRET',
      'DATABASE_URL'
    ];

    const missingSecrets = requiredSecrets.filter(secret => 
      !process.env[secret] || process.env[secret].includes('CANARY')
    );

    if (missingSecrets.length > 0) {
      throw new Error(`Missing or invalid secrets: ${missingSecrets.join(', ')}`);
    }

    this.secrets = { ...process.env };
  }

  get(secretName) {
    if (!this.initialized) {
      throw new Error('Secrets manager not initialized');
    }

    const value = this.secrets[secretName];
    if (!value) {
      throw new Error(`Secret ${secretName} not found`);
    }

    return value;
  }

  // Safe method to check if running with canary credentials
  hasCanaryCredentials() {
    return Object.values(this.secrets).some(value => 
      value && typeof value === 'string' && value.includes('CANARY')
    );
  }
}

// Singleton instance
module.exports = new SecretsManager();

