// Secure secrets management configuration
// Use AWS Secrets Manager, HashiCorp Vault, or similar in production

class SecretsManager {
  constructor() {
    this.secrets = new Map();
    this.initialized = false;
  }

  async initialize() {
    if (this.initialized) return;

    try {
      // In production, use actual secrets manager
      if (process.env.NODE_ENV === 'production') {
        await this.loadFromSecretsManager();
      } else {
        // In development/test, load from environment with validation
        await this.loadFromEnvironment();
      }

      this.initialized = true;
      console.log('Secrets manager initialized successfully');
    } catch (error) {
      console.error('Failed to initialize secrets manager:', error.message);
      throw error;
    }
  }

  async loadFromSecretsManager() {
    // Implement actual secrets manager integration
    // Example: AWS Secrets Manager, Azure Key Vault, HashiCorp Vault

    // For now, fallback to environment with enhanced validation
    await this.loadFromEnvironment();
  }

  async loadFromEnvironment() {
    const requiredSecrets = [
      'DATABASE_URL',
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY',
      'ANTHROPIC_API_KEY',
      'STRIPE_SECRET_KEY',
      'LOGFIRE_TOKEN'
    ];

    const missingSecrets = [];

    for (const secretName of requiredSecrets) {
      const value = process.env[secretName];

      if (!value) {
        missingSecrets.push(secretName);
        continue;
      }

      // Validate secret format
      if (this.isCanaryValue(value)) {
        console.warn(`⚠️  CANARY VALUE DETECTED: ${secretName} - This appears to be a test value`);
      }

      this.secrets.set(secretName, value);
    }

    if (missingSecrets.length > 0 && process.env.NODE_ENV === 'production') {
      throw new Error(`Missing required secrets: ${missingSecrets.join(', ')}`);
    }
  }

  getSecret(secretName) {
    if (!this.initialized) {
      throw new Error('Secrets manager not initialized');
    }

    const value = this.secrets.get(secretName);

    if (!value && process.env.NODE_ENV === 'production') {
      throw new Error(`Secret not found: ${secretName}`);
    }

    return value;
  }

  isCanaryValue(value) {
    // Detect canary values used for monitoring exfiltration
    return value && typeof value === 'string' && value.includes('CANARY');
  }

  // Mask secrets for logging
  maskSecret(value, visibleChars = 4) {
    if (!value || typeof value !== 'string') return '****';

    if (value.length <= visibleChars * 2) {
      return '*'.repeat(value.length);
    }

    const firstPart = value.substring(0, visibleChars);
    const lastPart = value.substring(value.length - visibleChars);
    return `${firstPart}****${lastPart}`;
  }
}

// Singleton instance
const secretsManager = new SecretsManager();

module.exports = secretsManager;

