// Environment variable validation and configuration
require('dotenv').config();

const Joi = require('joi');

// Define environment variable schema
const envVarsSchema = Joi.object({
  NODE_ENV: Joi.string()
    .valid('development', 'production', 'test')
    .default('development'),
  PORT: Joi.number().default(3000),

  // Required secrets - no default values!
  JWT_SECRET: Joi.string().required()
    .description('JWT secret key'),

  // Optional but recommended
  ALLOWED_ORIGIN: Joi.string().default('http://localhost:3000'),

  // Database secrets (if used)
  DB_HOST: Joi.string(),
  DB_PORT: Joi.number(),
  DB_NAME: Joi.string(),
  DB_USER: Joi.string(),
  DB_PASSWORD: Joi.string(),

}).unknown(); // Allow other env vars

const { value: envVars, error } = envVarsSchema.validate(process.env);

if (error) {
  throw new Error(`Config validation error: ${error.message}`);
}

module.exports = {
  env: envVars.NODE_ENV,
  port: envVars.PORT,
  jwt: {
    secret: envVars.JWT_SECRET,
  },
  cors: {
    origin: envVars.ALLOWED_ORIGIN,
  },
  // Add other config groups as needed
};

// Secrets manager integration - choose one approach

// Option 1: AWS Secrets Manager (recommended for production)
const getSecretsFromAWS = async () => {
  try {
    const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

    const client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1',
    });

    const command = new GetSecretValueCommand({
      SecretId: process.env.AWS_SECRET_NAME || 'app/secrets',
    });

    const response = await client.send(command);
    return JSON.parse(response.SecretString);
  } catch (error) {
    console.error('Failed to fetch secrets from AWS:', error.message);
    throw new Error('Secrets unavailable');
  }
};

// Option 2: HashiCorp Vault
const getSecretsFromVault = async () => {
  // Implementation for HashiCorp Vault
  throw new Error('Vault integration not implemented');
};

// Option 3: Local development fallback
const getSecretsFromEnv = () => {
  const requiredSecrets = ['JWT_SECRET'];
  const missingSecrets = requiredSecrets.filter(secret => !process.env[secret]);

  if (missingSecrets.length > 0) {
    throw new Error(`Missing required secrets: ${missingSecrets.join(', ')}`);
  }

  return {
    jwtSecret: process.env.JWT_SECRET,
    // Add other secrets as needed
  };
};

// Main function to get secrets
const getSecrets = async () => {
  if (process.env.USE_SECRETS_MANAGER === 'aws') {
    return await getSecretsFromAWS();
  } else if (process.env.USE_SECRETS_MANAGER === 'vault') {
    return await getSecretsFromVault();
  } else {
    return getSecretsFromEnv();
  }
};

module.exports = { getSecrets };

